	__asm__ __volatile__(".word\t0x81b00020");

	canjump = 0;
	accel |= MPEG2_ACCEL_SPARC_VIS2;

	signal (SIGILL, oldsig);
    }
#endif /* ACCEL_DETECT */

    return accel;
