#endif /* ARCH_SPARC */

#ifdef ARCH_ALPHA
static inline uint32_t arch_accel (uint32_t accel)
{
    if (accel & MPEG2_ACCEL_ALPHA_MVI)
	accel |= MPEG2_ACCEL_ALPHA;

#ifdef ACCEL_DETECT
    if (accel & MPEG2_ACCEL_DETECT) {
	uint64_t no_mvi;

