85: static int open_display (x11_instance_t * instance, int width, int height)
86: {
87:     int major;
88:     int minor;
89:     Bool pixmaps;
90:     XVisualInfo visualTemplate;
91:     XVisualInfo * XvisualInfoTable;
92:     XVisualInfo * XvisualInfo;
93:     int number;
94:     int i;
95:     XSetWindowAttributes attr;
96:     XGCValues gcValues;
97: 
98:     instance->display = XOpenDisplay (NULL);
99:     if (! (instance->display)) {
100: 	fprintf (stderr, "Can not open display\n");
101: 	return 1;
102:     }
103: 
104:     instance->xshm_extension = 0;
105:     if (XShmQueryVersion (instance->display, &major, &minor,
106: 			  &pixmaps) != 0 &&
107: 	(major > 1 || (major == 1 && minor >= 1))) {
108: 	instance->xshm_extension = 1;
109: 	instance->completion_type =
110: 	    XShmGetEventBase (instance->display) + ShmCompletion;
111:     } else
112: 	fprintf (stderr, "No xshm extension\n");
113: 
114:     /* list truecolor visuals for the default screen */
115: #ifdef __cplusplus
116:     visualTemplate.c_class = TrueColor;
117: #else
118:     visualTemplate.class = TrueColor;
119: #endif
120:     visualTemplate.screen = DefaultScreen (instance->display);
121:     XvisualInfoTable = XGetVisualInfo (instance->display,
122: 				       VisualScreenMask | VisualClassMask,
123: 				       &visualTemplate, &number);
124:     if (XvisualInfoTable == NULL) {
125: 	fprintf (stderr, "No truecolor visual\n");
126: 	return 1;
127:     }
128: 
129:     /* find the visual with the highest depth */
130:     XvisualInfo = XvisualInfoTable;
131:     for (i = 1; i < number; i++)
132: 	if (XvisualInfoTable[i].depth > XvisualInfo->depth)
133: 	    XvisualInfo = XvisualInfoTable + i;
134: 
135:     instance->vinfo = *XvisualInfo;
136:     XFree (XvisualInfoTable);
137: 
138:     attr.background_pixmap = None;
139:     attr.backing_store = NotUseful;
140:     attr.border_pixel = 0;
141:     attr.event_mask = 0;
142:     /* fucking sun blows me - you have to create a colormap there... */
143:     attr.colormap = XCreateColormap (instance->display,
144: 				     RootWindow (instance->display,
145: 						 instance->vinfo.screen),
146: 				     instance->vinfo.visual, AllocNone);
147:     instance->window =
148: 	XCreateWindow (instance->display,
149: 		       DefaultRootWindow (instance->display),
150: 		       0 /* x */, 0 /* y */, width, height,
151: 		       0 /* border_width */, instance->vinfo.depth,
152: 		       InputOutput, instance->vinfo.visual,
153: 		       (CWBackPixmap | CWBackingStore | CWBorderPixel |
154: 			CWEventMask | CWColormap), &attr);
155: 
156:     instance->gc = XCreateGC (instance->display, instance->window, 0,
157: 			      &gcValues);
158: 
159: #ifdef LIBVO_XV
160:     instance->adaptors = 0;
161:     instance->adaptorInfo = NULL;
162: #endif
163: 
164:     return 0;
165: }
