221: static void x11_event (x11_instance_t * instance)
222: {
223:     XEvent event;
224:     char * addr;
225:     int i;
226: 
227:     XNextEvent (instance->display, &event);
228:     if (event.type == instance->completion_type) {
229: 	addr = (instance->shminfo.shmaddr +
230: 		((XShmCompletionEvent *)&event)->offset);
231: 	for (i = 0; i < 3; i++)
232: 	    if (addr == instance->frame[i].data)
233: 		instance->frame[i].wait_completion = 0;
234:     }
235: }
