277: static int x11_alloc_frames (x11_instance_t * instance, int xshm)
278: {
279:     int size;
280:     char * alloc;
281:     int i = 0;
282: 
283:     if (xshm && !instance->xshm_extension)
284: 	return 1;
285: 
286:     size = 0;
287:     alloc = NULL;
288:     while (i < 3) {
289: 	instance->frame[i].wait_completion = 0;
290: 	instance->frame[i].ximage = xshm ?
291: 	    XShmCreateImage (instance->display, instance->vinfo.visual,
292: 			     instance->vinfo.depth, ZPixmap, NULL /* data */,
293: 			     &(instance->shminfo),
294: 			     instance->width, instance->height) :
295: 	    XCreateImage(instance->display, instance->vinfo.visual,
296: 			 instance->vinfo.depth, ZPixmap, 0, NULL /* data */,
297: 			 instance->width, instance->height, 8, 0);
298: 	if (instance->frame[i].ximage == NULL) {
299: 	    fprintf (stderr, "Cannot create ximage\n");
300: 	    return 1;
301: 	} else if (xshm) {
302: 	    if (i == 0) {
303: 		size = (instance->frame[0].ximage->bytes_per_line *
304: 			instance->frame[0].ximage->height);
305: 		alloc = (char *) create_shm (instance, 3 * size);
306: 	    } else if (size != (instance->frame[i].ximage->bytes_per_line *
307: 				instance->frame[i].ximage->height)) {
308: 		fprintf (stderr, "unexpected ximage data size\n");
309: 		return 1;
310: 	    }
311: 	} else
312: 	    alloc =
313: 		(char *) malloc (instance->frame[i].ximage->bytes_per_line *
314: 				 instance->frame[i].ximage->height);
315: 	instance->frame[i].data = instance->frame[i].ximage->data = alloc;
316: 	i++;
317: 	if (alloc == NULL) {
318: 	    while (--i >= 0)
319: 		XDestroyImage (instance->frame[i].ximage);
320: 	    return 1;
321: 	}
322: 	alloc += size;
323:     }
324: 
325:     instance->xshm = xshm;
326:     return 0;
327: }
