392: static int xv_check_fourcc (x11_instance_t * instance, XvPortID port,
393: 			    int fourcc, const char * fourcc_str)
394: {
395:     XvImageFormatValues * formatValues;
396:     int formats;
397:     int i;
398: 
399:     formatValues = XvListImageFormats (instance->display, port, &formats);
400:     for (i = 0; i < formats; i++)
401: 	if ((formatValues[i].id == fourcc) &&
402: 	    (! (strcmp (formatValues[i].guid, fourcc_str)))) {
403: 	    XFree (formatValues);
404: 	    return 0;
405: 	}
406:     XFree (formatValues);
407:     return 1;
408: }
