490: static void xv_teardown (x11_instance_t * instance)
491: {
492:     int i;
493: 
494:     for (i = 0; i < 3; i++) {
495: 	while (instance->frame[i].wait_completion)
496: 	    x11_event (instance);
497: 	XFree (instance->frame[i].xvimage);
498:     }
499:     if (instance->xshm)
500: 	destroy_shm (instance);
501:     else
502: 	free (instance->frame[0].data);
503:     XvUngrabPort (instance->display, instance->port, 0);
