507: static int common_setup (vo_instance_t * _instance, unsigned int width,
508: 			 unsigned int height, unsigned int chroma_width,
509: 			 unsigned int chroma_height,
510: 			 vo_setup_result_t * result)
511: {
512:     x11_instance_t * instance = (x11_instance_t *) _instance;
513: 
514:     if (instance->display != NULL) {
515: 	/* Already setup, just adjust to the new size */
516: 	if (instance->teardown != NULL)
517: 	    instance->teardown (instance);
518:         XResizeWindow (instance->display, instance->window, width, height);
519:     } else {
520: 	/* Not setup yet, do the full monty */
521:         if (open_display (instance, width, height))
522:             return 1;
523:         XMapWindow (instance->display, instance->window);
524:     }
525:     instance->vo.setup_fbuf = NULL;
526:     instance->vo.start_fbuf = NULL;
527:     instance->vo.set_fbuf = NULL;
528:     instance->vo.draw = NULL;
529:     instance->vo.discard = NULL;
530:     instance->vo.close = x11_close;
531:     instance->width = width;
532:     instance->height = height;
533:     instance->index = 0;
534:     instance->teardown = NULL;
535:     result->convert = NULL;
536: 
537: #ifdef LIBVO_XV
538:     if (instance->xv == 1 &&
539: 	(chroma_width == width >> 1) && (chroma_height == height >> 1) &&
540: 	!xv_check_extension (instance, FOURCC_YV12, "YV12") &&
541: 	!xv_alloc_frames (instance, 3 * width * height / 2, FOURCC_YV12)) {
542: 	instance->vo.setup_fbuf = xv_setup_fbuf;
543: 	instance->vo.start_fbuf = x11_start_fbuf;
544: 	instance->vo.draw = xv_draw_frame;
545: 	instance->teardown = xv_teardown;
546:     } else if (instance->xv && (chroma_width == width >> 1) &&
547: 	       !xv_check_extension (instance, FOURCC_UYVY, "UYVY") &&
548: 	       !xv_alloc_frames (instance, 2 * width * height, FOURCC_UYVY)) {
549: 	instance->vo.setup_fbuf = x11_setup_fbuf;
550: 	instance->vo.start_fbuf = x11_start_fbuf;
551: 	instance->vo.draw = xv_draw_frame;
552: 	instance->teardown = xv_teardown;
553: 	result->convert = mpeg2convert_uyvy;
554:     } else
555: #endif
556:     if (!x11_alloc_frames (instance, 1) || !x11_alloc_frames (instance, 0)) {
557: 	int bpp;
558: 
559: 	instance->vo.setup_fbuf = x11_setup_fbuf;
560: 	instance->vo.start_fbuf = x11_start_fbuf;
561: 	instance->vo.draw = x11_draw_frame;
562: 	instance->teardown = x11_teardown;
563: 
564: #ifdef WORDS_BIGENDIAN
565: 	if (instance->frame[0].ximage->byte_order != MSBFirst) {
566: 	    fprintf (stderr, "No support for non-native byte order\n");
567: 	    return 1;
568: 	}
569: #else
570: 	if (instance->frame[0].ximage->byte_order != LSBFirst) {
