134: static int create_window (dx_instance_t * instance)
135: {
136:     RECT rect_window;
137:     WNDCLASSEX wc;
138: 
139:     wc.cbSize        = sizeof (WNDCLASSEX);
140:     wc.style         = CS_DBLCLKS;
141:     wc.lpfnWndProc   = (WNDPROC) event_procedure;
142:     wc.cbClsExtra    = 0;
143:     wc.cbWndExtra    = 0;
144:     wc.hInstance     = GetModuleHandle (NULL);
145:     wc.hIcon         = NULL;
146:     wc.hCursor       = LoadCursor (NULL, IDC_ARROW);
147:     wc.hbrBackground = CreateSolidBrush (RGB (0, 0, 0));
148:     wc.lpszMenuName  = NULL;
149:     wc.lpszClassName = "libvo_dx";
150:     wc.hIconSm       = NULL;
151:     if (!RegisterClassEx (&wc)) {
152: 	fprintf (stderr, "Can not register window class\n");
153: 	return 1;
154:     }
155: 
156:     rect_window.top    = 10;
157:     rect_window.left   = 10;
158:     rect_window.right  = rect_window.left + instance->width;
159:     rect_window.bottom = rect_window.top + instance->height;
160:     AdjustWindowRect (&rect_window, WS_OVERLAPPEDWINDOW|WS_SIZEBOX, 0);
161: 
162:     instance->window = CreateWindow ("libvo_dx", "mpeg2dec",
163: 				     WS_OVERLAPPEDWINDOW | WS_SIZEBOX,
164: 				     CW_USEDEFAULT, 0,
165: 				     rect_window.right - rect_window.left,
166: 				     rect_window.bottom - rect_window.top,
167: 				     NULL, NULL, GetModuleHandle (NULL), NULL);
168:     if (instance->window == NULL) {
169: 	fprintf (stderr, "Can not create window\n");
170: 	return 1;
171:     }
172: 
173:     /* store a directx_instance pointer into the window local storage
174:      * (for later use in event_handler).
175:      * We need to use SetWindowLongPtr when it is available in mingw */
176:     SetWindowLong (instance->window, GWL_USERDATA, (LONG) instance);
177: 
178:     ShowWindow (instance->window, SW_SHOW);
179: 
180:     return 0;
181: }
