183: static LPDIRECTDRAWSURFACE2 alloc_surface (dx_instance_t * instance,
184: 					   DDSURFACEDESC * ddsd)
185: {
186:     LPDIRECTDRAWSURFACE surface;
187:     LPDIRECTDRAWSURFACE2 surface2;
188: 
189:     if (DD_OK != IDirectDraw2_CreateSurface (instance->ddraw, ddsd,
190: 					     &surface, NULL) ||
191: 	DD_OK != IDirectDrawSurface_QueryInterface (surface,
192: 						    &IID_IDirectDrawSurface2,
193: 						    (LPVOID *) &surface2)) {
194: 	fprintf (stderr, "Can not create directDraw frame surface\n");
195: 	return NULL;
196:     }
197:     IDirectDrawSurface_Release (surface);
198: 
199:     return surface2;
200: }
