202: static int dx_init (dx_instance_t *instance)
203: {
204:     HRESULT (WINAPI * OurDirectDrawCreate) (GUID *, LPDIRECTDRAW *,
205: 					    IUnknown *);
206:     LPDIRECTDRAW ddraw;
207:     DDSURFACEDESC ddsd;
208: 
209:     /* load direct draw DLL */
210:     instance->hddraw_dll = LoadLibrary ("DDRAW.DLL");
211:     if (instance->hddraw_dll == NULL) {
212: 	fprintf (stderr, "Can not load DDRAW.DLL\n");
213: 	return 1;
214:     }
215: 
216:     ddraw = NULL;
217:     OurDirectDrawCreate = (void *) GetProcAddress (instance->hddraw_dll,
218: 						   "DirectDrawCreate");
219:     if (OurDirectDrawCreate == NULL ||
220: 	DD_OK != OurDirectDrawCreate (NULL, &ddraw, NULL) ||
221: 	DD_OK != IDirectDraw_QueryInterface (ddraw, &IID_IDirectDraw2,
222: 					     (LPVOID *) &instance->ddraw) ||
223: 	DD_OK != IDirectDraw_SetCooperativeLevel (instance->ddraw,
224: 						  instance->window,
225: 						  DDSCL_NORMAL)) {
226: 	fprintf (stderr, "Can not initialize directDraw interface\n");
227: 	return 1;
228:     }
229:     IDirectDraw_Release (ddraw);
230: 
231:     memset (&ddsd, 0, sizeof (DDSURFACEDESC));
232:     ddsd.dwSize = sizeof (DDSURFACEDESC);
233:     ddsd.dwFlags = DDSD_CAPS;
234:     ddsd.ddsCaps.dwCaps = DDSCAPS_PRIMARYSURFACE;
235:     instance->display = alloc_surface (instance, &ddsd);
236:     if (instance->display == NULL) {
237: 	fprintf (stderr, "Can not create directDraw display surface\n");
238: 	return 1;
239:     }
240: 
241:     if (DD_OK != IDirectDraw2_CreateClipper (instance->ddraw, 0,
242: 					     &instance->clipper, NULL) ||
243: 	DD_OK != IDirectDrawClipper_SetHWnd (instance->clipper, 0,
244: 					     instance->window) ||
245: 	DD_OK != IDirectDrawSurface_SetClipper (instance->display,
246: 						instance->clipper)) {
247: 	fprintf (stderr, "Can not initialize directDraw clipper\n");
248: 	return 1;
249:     }
250: 
251:     return 0;
252: }
