303: static void * surface_addr (LPDIRECTDRAWSURFACE2 surface, int * stride)
304: {
305:     DDSURFACEDESC ddsd;
306: 
307:     memset (&ddsd, 0, sizeof (DDSURFACEDESC));
308:     ddsd.dwSize = sizeof (DDSURFACEDESC);
309:     IDirectDrawSurface2_Lock (surface, NULL, &ddsd,
310: 			      DDLOCK_NOSYSLOCK | DDLOCK_WAIT, NULL);
311:     IDirectDrawSurface2_Unlock (surface, NULL);
312:     *stride = ddsd.lPitch;
313:     return ddsd.lpSurface;
314: }
