338:     ddbltfx.dwDDFX = DDBLTFX_NOTEARING;
339:     if (DDERR_SURFACELOST ==
340: 	IDirectDrawSurface2_Blt (instance->display, &instance->window_coords,
341: 				 surface, NULL, DDBLT_WAIT, &ddbltfx)) {
342: 	/* restore surface and try again */
