381: static LPDIRECTDRAWSURFACE2 alloc_overlay (dx_instance_t * instance)
382: {
383:     DDSURFACEDESC ddsd;
384:     LPDIRECTDRAWSURFACE2 surface;
385: 
386:     memset (&ddsd, 0, sizeof (DDSURFACEDESC));
387:     ddsd.dwSize = sizeof (DDSURFACEDESC);
388:     ddsd.ddpfPixelFormat.dwSize = sizeof (DDPIXELFORMAT);
389:     ddsd.dwFlags = DDSD_HEIGHT | DDSD_WIDTH | DDSD_CAPS;
390:     ddsd.dwHeight = instance->height;
391:     ddsd.dwWidth = instance->width;
392:     ddsd.ddpfPixelFormat.dwFlags = DDPF_FOURCC;
393:     ddsd.ddpfPixelFormat.dwFourCC = FOURCC_YV12;
394:     ddsd.dwFlags |= DDSD_PIXELFORMAT;
395:     ddsd.ddsCaps.dwCaps = DDSCAPS_OVERLAY | DDSCAPS_VIDEOMEMORY;
396: #if USE_OVERLAY_TRIPLE_BUFFERING
397:     ddsd.dwFlags |= DDSD_BACKBUFFERCOUNT;
398:     ddsd.ddsCaps.dwCaps |= DDSCAPS_COMPLEX | DDSCAPS_FLIP;
399: #endif
400:     ddsd.dwBackBufferCount = 2;
401: 
402:     surface = alloc_surface (instance, &ddsd);
403:     if (surface == NULL)
404: 	fprintf (stderr, "Can not create directDraw frame surface\n");
405:     return surface;
406: }
