408: static int dx_setup (vo_instance_t * _instance, unsigned int width,
409: 		     unsigned int height, unsigned int chroma_width,
410: 		     unsigned int chroma_height, vo_setup_result_t * result)
411: {
412:     dx_instance_t * instance = (dx_instance_t *) _instance;
413:     LPDIRECTDRAWSURFACE2 surface;
414:     DDSURFACEDESC ddsd;
415: 
416:     if (common_setup (instance, width, height))
417: 	return 1;
418: 
419:     instance->overlay = alloc_overlay (instance);
420:     if (!instance->overlay)
421: 	return 1;
422:     update_overlay (instance);
423: 
424:     surface = instance->overlay;
425: 
426:     /* Get the back buffer */
427:     memset (&ddsd.ddsCaps, 0, sizeof (DDSCAPS));
428:     ddsd.ddsCaps.dwCaps = DDSCAPS_BACKBUFFER;
429:     if (DD_OK != IDirectDrawSurface2_GetAttachedSurface (instance->overlay,
430: 							 &ddsd.ddsCaps,
431: 							 &surface))
432: 	surface = instance->overlay;
433: 
434:     instance->yuv[0] = surface_addr (surface, &instance->stride);
435:     instance->yuv[2] = instance->yuv[0] + instance->stride * instance->height;
436:     instance->yuv[1] =
437: 	instance->yuv[2] + (instance->stride * instance->height >> 2);
438: 
439:     result->convert = NULL;
440:     return 0;
441: }
